    '.gitlab-ci.yml': 'include:\n  - project: vyriy/ci\n    ref: main\n    file: /ci.yml\n\nvariables:\n  JOB_RELEASE_DISABLED: \'1\'\n  JOB_E2E_DISABLED: \'1\'\n  JOB_AWS_DISABLED: \'1\'\n\ndocker:\n  script:\n    - |\n      set -eu\n\n      IMAGE_TAG="${CI_COMMIT_TAG:-$CI_PIPELINE_IID}"\n\n      echo "$CI_REGISTRY_PASSWORD" | docker login -u "$CI_REGISTRY_USER" --password-stdin "$CI_REGISTRY"\n\n      docker buildx build \\\n        --tag "$CI_REGISTRY_IMAGE/api:$IMAGE_TAG" \\\n        --tag "$CI_REGISTRY_IMAGE/api:latest" \\\n        --file workspaces/api/Dockerfile \\\n        --platform linux/arm64 \\\n        --provenance=false \\\n        --pull \\\n        --push \\\n        dist\n\n      docker buildx build \\\n        --tag "$CI_REGISTRY_IMAGE/storybook:$IMAGE_TAG" \\\n        --tag "$CI_REGISTRY_IMAGE/storybook:latest" \\\n        --file Dockerfile.static \\\n        --platform linux/arm64 \\\n        --provenance=false \\\n        --pull \\\n        --push \\\n        storybook-static\n\n      sshpass \\\n        -p "$SSH_PASSWORD" \\\n        ssh \\\n        -p "$SSH_PORT" \\\n        -o StrictHostKeyChecking=no \\\n        -o UserKnownHostsFile=/dev/null \\\n        "$SSH_USER@$SSH_VYRIY_HOST" \\\n        "$SSH_COMMAND"\n',
